import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"62、【小过】 艮下震上","description":"周易尚氏学 - 62、【小过】 艮下震上","frontmatter":{"title":"62、【小过】 艮下震上","description":"周易尚氏学 - 62、【小过】 艮下震上"},"headers":[],"relativePath":"zh/classics/shangshi/067.md","filePath":"zh/classics/shangshi/067.md"}'),s={name:"zh/classics/shangshi/067.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_62、【小过】-艮下震上" tabindex="-1">62、【小过】 艮下震上 <a class="header-anchor" href="#_62、【小过】-艮下震上" aria-label="Permalink to “62、【小过】 艮下震上”">​</a></h1><p>过之为义。彖传即不明释。故讫无定解。后儒于是有以经过为说者。端木国瑚谓兑巽过乾之左右。故曰大过。艮震过坤之左右。故曰小过。有以过越为说者。朱震谓大过阳过阴。大者过越也。小过四阴二阳。小者过越也。前一说人只见于端木氏。后一说则易家多从之。然尚有五阳五阴之卦。何以不言过。且汉人以大过为死卦。阳过盛而反死。又何说乎。如谓四阳为上下二阴所束缚故死。则小过四阴包二阳。胡以不谓之死乎。又四阳在中为大过。四阴在中何以不谓为小过。而必以四阴在外者为小过乎。是皆可疑。而先儒无言者。按太玄拟大玄过为失。云阴大作贼。阳不能得。言阳为阻贼。而失其用也。拟小过为羡为差。云阳气赞幽。推包羡爽。未得正行。言震阳本可直出。乃为上下四阴所包。推排曲抑。仍有羡爽。羡邪曲。爽差也。盖大过按卦气时当小雪。穷阴极寒。故阳气极衰。小过时当立春。阳气辟。本可无阻。乃为阴气所包。仍不免小有回曲。大小过纯以卦义言。不以阴阳多少言也。卦二五阴得中。二阴承重阳故亨。阴牝阳故利贞。阴得中故可小事。阳失位而不中。故不可大事。左传昭五年。筮遇明夷之谦曰。日之谦当鸟。日之谦即离变艮。变艮而曰当鸟。是以艮为鸟。易林本之。以艮为黔啄为鸟。详焦氏易诂小过下艮故曰鸟。上震故曰飞鸟。而震为覆艮。是上下皆鸟。故传曰有飞鸟之象焉。宋衷谓二阳在内。上下各二阴。有似飞鸟舒翮之象。虞翻则用卦变。云小过从晋来。晋上离为鸟。惠士奇谓古飞非通用。小过即非字象。故曰飞鸟。愈演愈寄。皆艮鸟象失传之过也。遗送也。震为音。茹敦和云。下艮为反震。口向下若送音于人者。故飞鸟遗之音。上谓五。五失位而乘阳。正谓二。二当位而承阳。故上不宜而下大吉也。</p><p>彖曰。小过。小者过而亨也。过以利贞。与时行也。柔得中。是以小事吉也。刚失位而不中。是以不可大事也。有飞鸟之象焉。飞鸟道之音。不宜上宜下。大吉。上边而下顺也。</p><p>艮为时。刚失位指四。不中指三。有飞鸟之象。谓上下卦皆艮也。非如宋衷之解。艮为鸟。上艮覆故曰逆。下反是故顺。又五乘刚故逆。二承阳故顺。</p><p>象曰。山上有雷。小过。君子以行过乎恭。</p><p>丧过乎哀。用过乎俭。震为行。恭或为艮象。兑毁折故曰丧。震为乐。震反为艮。故为哀。俭亦或为艮止象。旧解皆用卦变。无确诂。姑测其义如此。又三者皆过之微。即治小过之义也。</p><p>初六。飞鸟以凶。</p><p>艮为鸟。四虽有应。二得敌。应予阻格。又失位。故凶。</p><h3 id="象曰。飞鸟以凶。不可如何也。" tabindex="-1">象曰。飞鸟以凶。不可如何也。 <a class="header-anchor" href="#象曰。飞鸟以凶。不可如何也。" aria-label="Permalink to “象曰。飞鸟以凶。不可如何也。”">​</a></h3><p>言应困难。</p><p>六二。过其祖。遇其妣。不及其君。遇其臣，无咎。</p><p>艮为祖。二承三故过其祖。巽为妣。二当巽初。故遇其妣。尔雅母曰妣。妣谓二。祖谓三。二应在五。五震为君。乃五不应。故不及其君。良为臣。三艮主爻。二承之。故遇其臣。艮为祖。翼为母。震君艮臣象皆失传。故旧解无通者。义详焦氏易诂。</p><h3 id="象曰。不及其君。臣不可过也。" tabindex="-1">象曰。不及其君。臣不可过也。 <a class="header-anchor" href="#象曰。不及其君。臣不可过也。" aria-label="Permalink to “象曰。不及其君。臣不可过也。”">​</a></h3><p>传义未详。旧说或昆仑。或浮泛。皆不安。</p><p>九三。弗过防之。从或戕之。凶。</p><p>四遇敌故弗过。艮为守为坚。下有群阴承之。利于防守。故曰防之。与渐九三。蒙上九利御寇。义同也。三应在上。戕害也。从或戕之者。言三若应上。则四或害之也。艮为刀剑。四艮反向下。故戕之。首回防之。所以戒也。</p><h3 id="象曰。从或戕之。凶何如也。" tabindex="-1">象曰。从或戕之。凶何如也。 <a class="header-anchor" href="#象曰。从或戕之。凶何如也。" aria-label="Permalink to “象曰。从或戕之。凶何如也。”">​</a></h3><p>极言其凶。</p><p>九四。无咎。弗过遇之。往厉必戒。匆用永贞。</p><p>四临重阻。利往。故无咎。四应在初。遇谓遇三也。三为四敌。故戒以弗过。然而遇之。往厉者。谓往应初而厉也。往应初。则三戕之。故厉。厉则宜有所戒。勿用而贞定自守可也。无咎指上行。弗过指下行。昔贤皆泥于往外为往。岂知需上云。三人来。是往外而日来。睽上云。往遇雨。是来内而曰往。易团于往来不执定例也。</p><h3 id="象曰。弗过遇之。位不当也。往厉必戒。终不可长也。" tabindex="-1">象曰。弗过遇之。位不当也。往厉必戒。终不可长也。 <a class="header-anchor" href="#象曰。弗过遇之。位不当也。往厉必戒。终不可长也。" aria-label="Permalink to “象曰。弗过遇之。位不当也。往厉必戒。终不可长也。”">​</a></h3><p>言之初仍勿用为宜。终不可长。</p><p>六五。密云不雨。自我西郊。公弋取彼在穴。</p><p>文言以坤为云。五上重阴。故曰密云。兑为雨。风火在下。故不雨。兑西震东。言此密云起自西郊。而东行也。震为公为射。故曰公弋。七者系绳于矢以射鸟。乃不射身而以上取彼在穴之艮狐。胡能得乎。盖五应在二。二巽为绳。艮为矢。以绳系矢。七象也。而艮为穴为孤。艮手为取。穴居之物。岂能弋取。言二不应五。有如此也。凡易取象。不于本变必于应。应爻有应予。如明夷初交应在四震。则曰飞。曰翼。曰攸往。曰主人有言。全取震象。而直言之。应爻无应予。亦往往取其象而明其不应。如归妹上六应在三兑。则曰女承筐。曰士圭（右刀）羊。女与羊皆兑象。而三不应上。故又曰无实无血。及此爻皆是也。旧解不知此例。见象无着。则用卦变以当之。于是易义遂亡于讲说矣。</p><h3 id="象曰。密云不雨。已上也。" tabindex="-1">象曰。密云不雨。已上也。 <a class="header-anchor" href="#象曰。密云不雨。已上也。" aria-label="Permalink to “象曰。密云不雨。已上也。”">​</a></h3><p>巳上与小畜之上往同义。</p><p>上六。弗遇过之。飞鸟离之。凶。是谓灾音。</p><p>弗遇言为五所格。应三难也。乃竟过之。是无心相值。不虞之祸。盖艮为鸟。上卦艮覆。鸟首向下有坠象。而艮为刀兵。正坠兵刃之上。离罹通。道也。遭此意外之祸。故凶也。三巽体。巽为疾病。故为灾眚。是谓灾眚者。言祸非由己。致无妄之灾。不可如何也。</p><h3 id="象曰。弗遇过之。巳亢也。" tabindex="-1">象曰。弗遇过之。巳亢也。 <a class="header-anchor" href="#象曰。弗遇过之。巳亢也。" aria-label="Permalink to “象曰。弗遇过之。巳亢也。”">​</a></h3><p>虞翻云。飞下称亢。按说文。亢人颈。或从页。是亢即颃。古通为一字。诗邶风颌之颃之。毛传飞而上曰颉。飞而下回颃。故前书扬雄传解嘲。邹行以颉亢而取世资。颃即作亢。师古云。颉亢上下不定也。亦训亢为下。上卦艮鸟覆有坠象。故曰亢。已亢者。言飞鸟离灾而下也。李道平云。阳言亢。阴不言亢。故虞不从俗说。闻见录云。唐张师为赞皇尉。梦白鸟飞翔坠于云际。召黄贺筮之。遇小过。曰。雷震山上。鸟坠云间。声迹两销。不可复见。委心顺命可也。是亦以艮为鸟。艮覆故曰鸟坠。互大坎故曰云间。震为声迹。坎隐伏。故曰声道两销。不可复见。是亢之为下。再见于唐人所释。以艮覆为鸟坠。黄贺独知也。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
